INSERT INTO farm_models (id, area, position, content) VALUES
  ('kitchen-garden', 'vuon', 0, '{"title":"Rau ăn lá và rau gia vị theo lứa","fit":"Gần nhà, tiện tưới và có chỗ thoát nước. Phù hợp nếu bố mẹ muốn có rau dùng trước, bán phần thu dư sau.","care":"Kiểm tra đất, tưới và bắt sâu theo thời tiết. Thu hái và soạn rau vào ngày có người lấy.","pilot":"Chọn góc gần nước và vài loại gia đình thường ăn. Chia làm hai đợt gieo để thu rải. Dùng phương án 15 hoặc 30 m² trên biểu đồ tùy công chăm.","costs":"Hạt hoặc cây giống, vật tư làm luống, nước tưới, rổ và bao gói nếu có bán.","outlet":"Dùng trong nhà, sau đó hỏi hàng xóm hoặc quán ăn gần xem họ lấy loại nào và nhận vào ngày nào.","decision":"Qua một lứa, ghi lượng nhà dùng, lượng bán được, rau hỏng và công tưới. Mở rộng khi bố mẹ thấy công chăm vừa sức và phần dư có người lấy đều.","sources":[{"label":"Sở KH&CN TP.HCM · Kỹ thuật trồng rau","url":"https://dost.hochiminhcity.gov.vn/mo-hinh-ung-dung-trong-nong-nghiep/ky-thuat-trong-rau-an/"},{"label":"Khuyến nông Đà Nẵng · Hướng dẫn trồng rau ăn lá","url":"https://khuyennong.danang.gov.vn/chi-tiet-tin/group/3/nid/2210/huong-dan-ky-thuat-trong-cac-loai-rau-an-la-theo-huong-huu-co"}]}'),
  ('seedling-trays', 'vuon', 1, '{"title":"Ươm cây giống rau theo đợt đặt","fit":"Có góc vườn thuận tiện đặt khay và quanh nhà có người trồng rau cùng vụ. Bố mẹ có thể làm từng đợt nhỏ rồi giao tại nhà.","care":"Kiểm tra khay và độ ẩm mỗi ngày trong giai đoạn ươm. Công giao cây tập trung vào đầu vụ.","pilot":"Hỏi trước giống mọi người cần và ngày họ định trồng. Ươm thử vài khay của một loại rau đang vào vụ hoặc dùng số cây đó cho vườn nhà.","costs":"Hạt giống, khay, giá thể, nước và công loại cây yếu.","outlet":"Giao cây cho người trồng rau quanh xã hoặc cửa hàng vật tư có hỏi mua trước.","decision":"Ghi số cây đạt, số cây được lấy đúng hẹn và tỷ lệ còn dư. Chỉ tăng số khay khi lịch lấy cây lặp lại qua các đợt.","sources":[{"label":"Sở KH&CN Đồng Nai · Tài liệu gieo ươm cây rau trên giá thể","url":"https://nguontin.khcndongnai.gov.vn/wp-content/uploads/2021/11/2016-NN-126.pdf"}]}'),
  ('fruit-corner', 'vuon', 2, '{"title":"Góc cây ăn quả theo giống địa phương","fit":"Có góc đủ sáng, dễ đi lại và cây mới có chỗ phát triển. Phù hợp mục tiêu dùng trong nhà và thu theo mùa.","care":"Tưới và quan sát khi cây còn nhỏ. Công thường tăng lúc cần tỉa, xử lý sâu hại hoặc thu hái.","pilot":"Giữ những cây đang cho quả. Nếu muốn trồng thêm, thử vài cây giống được nhà vườn gần đó trồng ổn trên nền đất tương tự, chẳng hạn ổi hoặc chanh nếu hợp địa phương.","costs":"Cây giống, cọc, nước tưới và vật tư chăm sóc theo loại cây.","outlet":"Dùng quả tại nhà và hỏi mối chợ hoặc khách quanh làng xem họ lấy giống quả nào theo mùa.","decision":"Chờ qua mùa nắng hoặc mưa đầu tiên để đánh giá cây, công chăm và chỗ tán sẽ che đất. Tính riêng thời gian chờ tới lứa thu.","sources":[{"label":"Khuyến nông Quốc gia · Nguyên tắc chọn đất và chăm vườn cây ăn quả","url":"https://khuyennongvn.gov.vn/khoa-hoc-cong-nghe/khcn-trong-nuoc/nguyen-tac-trong-va-cham-soc-vuon-cay-an-qua-bao-dam-ve-sinh-an-toan-thuc-pham-5922.html"}]}'),
  ('freshwater-fish', 'ao', 3, '{"title":"Nuôi thử cá nước ngọt trong ao sẵn có","fit":"Cần ao giữ nước theo vụ, nguồn nước phù hợp, bờ an toàn và người có thể theo dõi hằng ngày.","care":"Cho ăn, quan sát nước và cá hằng ngày. Cần người hỗ trợ khi thu hoạch, trời mưa lớn hoặc nguồn nước thay đổi.","pilot":"Đo mặt ao và độ sâu từng khu, hỏi về mức nước mùa khô và đường nước vào ra. Nhờ khuyến nông địa phương xem ao để chọn loài, mùa và quy mô thử phù hợp.","costs":"Con giống, thức ăn, kiểm tra nước, lưới và công theo dõi. Tính thêm chi phí bơm nếu địa điểm cần.","outlet":"Hỏi trước người thu mua hoặc hàng xóm về loại cá họ lấy, cỡ cá và số lượng một lần.","decision":"Chốt được nguồn nước, người trực ao và đầu ra trước khi thả. Sau lứa thử, đối chiếu lượng cá bán, thực phẩm dùng trong nhà và chi phí thức ăn.","sources":[{"label":"Khuyến nông Quốc gia · Điều kiện ao và hướng dẫn nuôi cá rô phi","url":"https://khuyennongvn.gov.vn/ky-thuat-thuy-san/ky-thuat-nuoi-ca-ro-phi-thuong-pham-15838.html"},{"label":"Khuyến nông Quốc gia · Theo dõi ao cá trong mùa lạnh","url":"https://khuyennongvn.gov.vn/khoa-hoc-cong-nghe/khcn-trong-nuoc/mot-so-bien-phap-ky-thuat-nuoi-ca-ro-phi-don-tinh-duc-qua-dong-14843.html"}]}'),
  ('lotus-containers', 'ao', 4, '{"title":"Sen chậu ở góc gần ao","fit":"Có chỗ nắng, nền chắc và đường đi thuận tiện ven ao. Có thể dùng chậu riêng để thử ít cây.","care":"Theo dõi nước, lá và nụ. Cần thêm công tách và vận chuyển nếu bán chậu.","pilot":"Hỏi cửa hàng hoa hoặc người mua gần nhà họ cần sen chậu hay hoa cắt. Nếu có người quan tâm, làm vài chậu ở vị trí thuận tay chăm để theo dõi được một mùa.","costs":"Chậu, giống sen, vật tư trồng, nước và công vận chuyển.","outlet":"Liên hệ cửa hàng hoa hoặc người chơi cây ở gần để thỏa thuận lấy tại vườn, nhất là khi chậu nặng.","decision":"Ghi số chậu có hoa, công chăm và lượng khách thực sự lấy. Hỏi hướng dẫn địa phương trước khi tính trồng vào lòng ao.","sources":[{"label":"Cổng thông tin Đắk Lắk · Tài liệu mô hình hoa sen trồng chậu","url":"https://daklak.gov.vn/documents/10181/4211951/208832-PH__L_C_I.___nh_m_c_kinh_t__-_k__thu_t_l_nh_v_c_tr_ng_tr_t.signed.pdf?version=1.0"},{"label":"Khuyến nông Ninh Bình · Chăm sóc cây sen","url":"https://khuyennong.ninhbinh.gov.vn/khoa-hoc-ky-thuat/ky-thuat-va-cham-soc-sen-798.html"}]}'),
  ('drained-field-mung-beans', 'ruong', 5, '{"title":"Đậu xanh trên ruộng thoát nước","fit":"Phù hợp khi ruộng rút nước tốt sau mưa, có lịch gieo phù hợp và điều kiện sử dụng đất cho phép.","care":"Công dồn lúc làm đất, gieo và thu hái. Sau mưa cần kiểm tra nước đọng.","pilot":"Hỏi xã hoặc hợp tác xã về việc đổi cây trên đất lúa. Xem ruộng rút nước ra sao rồi thử một dải ruộng đủ nhỏ để gia đình có thể tự thu.","costs":"Giống, công làm đất, tưới khi cần, thu hái, phơi và tách hạt.","outlet":"Dùng đậu trong nhà hoặc hỏi đại lý thu mua về lượng tối thiểu và yêu cầu hạt khô trước khi gieo.","decision":"Tính thời gian làm đất, hái và phơi cùng lượng hạt dùng được sau thu. Ruộng thường xuyên đọng nước thì xem phương án làm lúa cùng lịch xóm.","sources":[{"label":"Khuyến nông Quốc gia · Mô hình đậu xanh trên đất lúa thiếu nước","url":"https://khuyennongvn.gov.vn/hoat-dong-khuyen-nong/chuyen-giao-tbkt/quang-tri-hieu-qua-mo-hinh-chuyen-doi-cay-dau-xanh-tren-dat-lua-thieu-nuoc-17502.html"},{"label":"Cổng Thông tin điện tử Chính phủ · Văn bản về đất trồng lúa","url":"https://vanban.chinhphu.vn/default.aspx?docid=211120&pageid=27160"}]}'),
  ('rice-with-local-service', 'ruong', 6, '{"title":"Làm lúa một vụ cùng lịch xóm","fit":"Ruộng phù hợp trồng lúa, có lịch lấy nước cùng xóm và máy hoặc người làm dịch vụ nhận thửa nhỏ.","care":"Công dồn theo vụ. Có thể thuê làm đất và thu hoạch nếu dịch vụ tới được ruộng.","pilot":"Hỏi hộ liền ruộng hoặc hợp tác xã về lịch vụ, lối máy vào và báo giá trọn vụ. Nếu cần, ghép lịch thuê máy với ruộng bên cạnh.","costs":"Giống, vật tư, nước, phí dịch vụ làm đất và thu hoạch, phơi hoặc xay xát.","outlet":"Ưu tiên gạo ăn trong nhà. Nếu định bán, hỏi nơi thu mua có nhận lượng nhỏ hay gom chung qua hợp tác xã.","decision":"Chốt lịch và giá dịch vụ trước khi xuống giống. Sau khi thu, so chi phí và công với lượng thóc, gạo gia đình dùng được.","sources":[{"label":"Khuyến nông Quốc gia · Ví dụ phối hợp làm đất và gặt bằng máy ở Hiệp Hòa","url":"https://khuyennongvn.gov.vn/hoat-dong-khuyen-nong/chuyen-giao-tbkt/bac-giang-nhan-rong-mo-hinh-canh-dong-khong-dau-chan-tai-hiep-hoa-30567.html"}]}');
INSERT INTO farm_evidence (id, area, position, content) VALUES
  ('kon-braih-garden', 'vuon', 0, '{"title":"Một phương án cho vườn 200–dưới 500 m²","observed":"Kế hoạch cải tạo vườn tạp của xã Kon Braih, Quảng Ngãi năm 2026 dành khoảng 40 m² cho rau, đậu và cây khác trong nhóm vườn này. Đây là định hướng bố trí của xã.","application":"Vườn nhà khoảng 300 m² có thể dành một góc nhỏ 15–30 m² để thử trước. Chọn góc tiện tưới, giữ cây đang cho quả và tính cả lối đi.","source":{"label":"UBND xã Kon Braih · Kế hoạch cải tạo vườn tạp 2026","url":"https://konbraih.quangngai.gov.vn/upload/2007084/20260309/K%E1%BA%BF%20ho%E1%BA%A1ch%20v%E1%BB%81%20vi%E1%BB%87c%20th%E1%BB%B1c%20hi%E1%BB%87n%20c%E1%BA%A3i%20t%E1%BA%A1o%20v%C6%B0%E1%BB%9Dn%20t%E1%BA%A1p%20tr%C3%AAn%20%C4%91%E1%BB%8Ba%20b%C3%A0n%20x%C3%A3%20n%C4%83m%202026.pdf"}}'),
  ('dai-hue-herbs', 'vuon', 1, '{"title":"Gieo gối rau gia vị","observed":"Khuyến nông Quốc gia đưa tin tháng 3/2026 về Đại Huệ, Nghệ An. Tại mô hình, một số rau như mùi, thì là và húng quế cho thu sau khoảng 25–35 ngày.","application":"Chọn giống theo vụ ở quê mình và chia hai đợt gieo. Dùng ngày thu thực tế tại vườn để hẹn khách lấy, vì rét, mưa hoặc nắng có thể làm thay đổi lịch.","source":{"label":"Khuyến nông Quốc gia · Mô hình rau gia vị Đại Huệ","url":"https://khuyennongvn.gov.vn/hoat-dong-khuyen-nong/chuyen-giao-tbkt/hieu-qua-mo-hinh-chuyen-doi-trong-rau-gia-vi-tai-xa-dai-hue-tinh-nghe-an-31931.html"}}'),
  ('tuyen-quang-seedlings', 'vuon', 2, '{"title":"Ươm theo số cây đã hẹn","observed":"Tài liệu đăng trên cổng xúc tiến Tuyên Quang mô tả ươm rau trên các loại khay 40–84 lỗ, có che chắn phù hợp.","application":"Hỏi ngày khách cần cây rồi mới gieo vài khay. Ghi số cây khỏe được lấy. Số lỗ trên khay chỉ dùng để tính quy mô gieo.","source":{"label":"Cổng xúc tiến Tuyên Quang · Tài liệu kỹ thuật rau ăn lá","url":"https://apictt.tuyenquang.gov.vn/uploads/attachments/cay-rau-an-la-final.pdf"}}'),
  ('ha-noi-market-price', 'vuon', 3, '{"title":"Giá bán lẻ biến động sau mưa","observed":"Ngày 20/9/2026, VOV ghi nhận tại một số chợ Hà Nội giá rau cải khoảng 30.000 đồng/kg, gấp ba tuần trước trong đợt mưa lớn kéo dài.","application":"Hỏi giá người mua gần nhà thực trả theo bó hoặc kg ở tuần bình thường. Dùng giá tại vườn và số đã bán để tính hiệu quả của lứa thử.","source":{"label":"VOV · Khảo sát chợ Hà Nội ngày 20/9/2026","url":"https://vov.gov.vn/gia-rau-xanh-o-ha-noi-tang-vot-sau-mua-lon-keo-dai-dtnew-1165740"}}'),
  ('huong-hoa-pond', 'ao', 4, '{"title":"Ao nhỏ vẫn cần theo dõi qua mùa mưa","observed":"Hướng Hóa, Quảng Trị triển khai 10 mô hình cá nước ngọt trên tổng diện tích hơn 5.000 m² năm 2017. Mô hình có hỗ trợ kỹ thuật. Báo cáo ghi nhận nước mưa từ sườn đồi có thể kéo phù sa xuống ao.","application":"Xem ao sau mưa và hỏi mực nước thấp nhất mùa khô. Nhờ người có chuyên môn tại địa phương xem ao trước khi chọn cá và quy mô thử.","source":{"label":"Khuyến nông Quốc gia · Ca ao hộ ở Hướng Hóa","url":"https://khuyennongvn.gov.vn/chuong-trinh-nganh-nong-nghiep/tai-co-cau-nganh-nong-nghiep/quang-tri-nang-cao-hieu-qua-nuoi-ca-o-huyen-mien-nui-huong-hoa-16242.html"}}'),
  ('bac-ninh-pond', 'ao', 5, '{"title":"Công cho ăn và thu hoạch ở ao hàng hóa","observed":"Một hộ Bắc Ninh được ghi nhận năm 2024 có khoảng 2 ha mặt ao, sử dụng thiết bị hỗ trợ, gia đình trông hằng ngày và thuê thêm người khi thu hoạch.","application":"Lấy cách tách công trông ao và công thu hoạch để lập dự toán. Quy mô lứa thử nhà mình cần tính từ ao thực tế, báo giá thức ăn và người có thể phụ bắt cá.","source":{"label":"Khuyến nông Quốc gia · Ca nuôi cá nước ngọt tại Bắc Ninh","url":"https://khuyennongvn.gov.vn/guong-san-xuat-gioi/bac-ninh-hieu-qua-kinh-te-tu-mo-hinh-nuoi-ca-nuoc-ngot-27947.html"}}'),
  ('ha-tinh-beans', 'ruong', 6, '{"title":"Năng suất cây đậu theo vụ và địa phương","observed":"Phụ lục của Hà Tĩnh ghi nhóm cây đậu vụ Hè Thu 2025 bình quân 9,31 tạ/ha trên 2.156 ha. Đây là số tổng hợp toàn tỉnh cho nhóm cây đậu.","application":"Dùng để hiểu kết quả có phạm vi theo địa phương và theo nhóm cây. Với dải ruộng thử, cân hạt khô thực thu và ghi số công hái, phơi rồi mới tính đầu ra.","source":{"label":"Sở NN&MT Hà Tĩnh · Đề án Hè Thu 2026, phụ lục kết quả 2025","url":"https://dhtn.hatinh.gov.vn/Files/Others/AttachmentDto/d6a532a3-6eb3-4de7-b95f-1cbde5a94a77/21.4.2026DAHeThu2026bh_signed_haint.snnmt_2104202617420121.04.2026_22h39p48_signed.pdf"}}'),
  ('thach-xuan-machines', 'ruong', 7, '{"title":"Giá thuê máy vụ Xuân tại Thạch Xuân","observed":"UBND xã Thạch Xuân, Hà Tĩnh báo mức 180.000 đồng/sào cho máy gặt và 230.000 đồng/sào cho máy cày trong vụ Xuân 2026.","application":"Hỏi chủ máy ở quê mình báo riêng tiền cày và gặt, giá tối thiểu cho thửa nhỏ và phần phát sinh khi lối vào khó.","source":{"label":"UBND xã Thạch Xuân · Cuộc làm việc về thu hoạch vụ Xuân 2026","url":"https://thachxuan.hatinh.gov.vn/vi/bai-viet/ubnd-xa-thach-xuan-to-chuc-cuoc-lam-viec-ve-trien-khai-thu-hoach-lua-vu-xuan-nam-2026"}}'),
  ('nam-tien-hai-machines', 'ruong', 8, '{"title":"Ghép lịch gặt ở Nam Tiền Hải","observed":"UBND xã Nam Tiền Hải, Hưng Yên tổ chức 30 máy gặt tập trung và thống nhất mức tối đa 130.000 đồng/sào trong vụ Mùa 2026.","application":"Hỏi xem ruộng bên cạnh cấy và gặt khi nào, có thể ghép lịch máy không. So báo giá theo diện tích m² hoặc theo cả thửa vì cách tính sào có thể khác theo vùng.","source":{"label":"UBND xã Nam Tiền Hải · Tổ chức thu hoạch vụ Mùa 2026","url":"https://namtienhai.hungyen.gov.vn/nam-tien-hai-tap-trung-khan-truong-hoan-thanh-thu-hoach-vu-mua-va-hoan-thanh-cac-chi-tieu-thu-nop-na-c21369.html"}}');
INSERT INTO farm_plan (id, content) VALUES (1, '{"strategy":{"vuon":{"title":"Bắt đầu ở vườn","summary":"Dùng rau ăn lá và rau gia vị để thử đầu ra gần nhà. Khi quanh xã có người hẹn ngày lấy cây, thử vài khay giống như một đợt riêng.","decision":"Nếu bố mẹ chỉ có ít thời gian mỗi ngày, chọn phương án 15 m². Nếu hay vắng nhiều ngày, chỉ gieo khi có người thay tưới. Giữ phần vườn còn lại để bảo toàn cây đang cho quả và lối đi."},"ao":{"title":"Đánh giá ao trước khi mua giống","summary":"Đo diện tích mặt nước, mức sâu mùa khô, nguồn cấp và đường thoát. Hỏi khuyến nông xã và hộ nuôi gần nhất về mùa phù hợp, thức ăn, điện bơm và công trông ao.","decision":"Chỉ tính lứa cá khi có nguồn nước phù hợp, người theo dõi mỗi ngày và người mua nhận đúng cỡ hoặc gia đình có nhu cầu dùng. Nếu chưa đủ, giữ ao hiện trạng và xét sen chậu ở nền ven ao chắc, nếu có khách lấy tại vườn."},"ruong":{"title":"Chọn theo nước và lịch vụ","summary":"Ruộng rút nước tốt sau mưa thì hỏi xã về chuyển cây và thử một dải đậu xanh. Ruộng chủ động nước theo lịch xóm và có máy nhận thửa nhỏ thì cân nhắc làm một vụ lúa để lấy gạo.","decision":"Xin báo giá theo thửa hoặc m², gồm cày, gặt và đường đưa máy vào. Nếu công tự làm và phí máy vượt mức gia đình muốn dành cho một vụ, hỏi hộ liền ruộng để ghép lịch máy hoặc đợi vụ phù hợp."}},"gardenArea":300,"gardenPlans":[{"id":"regular","label":"Chăm đều hằng ngày","leafArea":20,"herbArea":10},{"id":"limited","label":"Ít thời gian mỗi ngày","leafArea":10,"herbArea":5}],"rollout":[{"period":"Tuần đầu","action":"Chọn góc vườn dễ tưới. Hỏi 3–5 nhà gần và một quán ăn về loại rau họ mua, ngày lấy và giá họ thực trả. Bố mẹ chọn mức công chăm vừa sức, còn con có thể phụ ghi chi phí và gom đơn."},{"period":"Lứa đầu","action":"Thử 15–30 m² với ít loại quen dùng và chia hai đợt gieo. Ghi riêng lượng dùng, lượng bán, rau hỏng và thời gian chăm. Cùng lúc đo mặt ao, hỏi mực nước mùa khô, xem ruộng sau mưa và hỏi lịch máy."},{"period":"Mốc 60–90 ngày","action":"Rà lại kết quả các lứa đã thu. Nếu trồng để bán, ưu tiên tăng một luống khi qua hai lứa công chăm vẫn vừa sức và đã có người mua lại. Nếu chủ yếu dùng ở nhà, giữ diện tích đủ ăn. Chỉ bắt đầu thêm một việc ở ao hoặc ruộng khi đã rõ điều kiện tại chỗ."}]}');
